```bash
cat <<'EOF' > reproduce_issue.py
import autograd.numpy as np
from autograd import grad

# Simple test case
x = np.array([1.0, 2.0, 3.0])
result = np.atleast_1d(x)
print("Simple case result:", result)  # This works fine

# But when used with autograd
def test_func(x):
    return np.sum(np.atleast_1d(x))

try:
    grad_func = grad(test_func)
    x = np.array([1.0, 2.0, 3.0])
    result = grad_func(x)  # This should raise UnboundLocalError
    print("Gradient result:", result)
except Exception as e:
    print(f"Error: {type(e).__name__}: {e}")

# Also test atleast_2d and atleast_3d
def test_func_2d(x):
    return np.sum(np.atleast_2d(x))

def test_func_3d(x):
    return np.sum(np.atleast_3d(x))

for func_name, test_func in [("atleast_2d", test_func_2d), ("atleast_3d", test_func_3d)]:
    try:
        grad_func = grad(test_func)
        x = np.array([1.0, 2.0, 3.0])
        result = grad_func(x)
        print(f"{func_name} gradient result:", result)
    except Exception as e:
        print(f"{func_name} error: {type(e).__name__}: {e}")
EOF
